    "6-0": "country",
    "6-1": "_(recomendado)_  \nPaís do hotel.  \n**Max. 2 chars, string.**",
    "7-0": "category",
    "7-1": "_(recomendado)_  \nCategoria do hotel.  \n**Max. 100 chars, string.**",
    "8-0": "rooms",
    "8-1": "_(obrigátorio)_  \nObjeto com informações dos quartos do hotel.  \n**Max. 20 itens, array.**"
